Same issue as #8856 — tmp files not cleaned up. A Stop hook handles this:
```bash
find . -maxdepth 1 -name 'tmpclaude-*-cwd' -mmin +5 -delete 2>/dev/null
find /tmp -maxdepth 1 -name 'claude-*-cwd' -mmin +5 -delete 2>/dev/null
find /tmp -maxdepth 1 -name 'claude-*' -type d -mmin +60 -exec rm -rf {} + 2>/dev/null
exit 0
```
```jsonc
{
  "hooks": {
    "Stop": [{
      "hooks": [{ "type": "command", "command": "bash ~/.claude/hooks/cleanup-tmp.sh" }]
    }]
  }
}
```
